/* dkcore str: views, search, strip, split, partition, replace, join, padding, the builder and the UTF-8 / UTF-16
 * conversions. Each function reproduces the CPython 3.14 str method it is named after, edge cases included; the
 * tests compare against a corpus generated by CPython (tests/str_corpus.h).
 *
 * Text is UTF-8. Where Python counts code points the code decodes them with dk_u8_next; a byte that is not part of
 * a valid sequence counts as one code point U+FFFD (the Python side would have had surrogateescape or an error). */
#include "dk/dk.h"

#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>

#include "str_internal.h"

/* ---- views -------------------------------------------------------------------------------------------------------- */

DkStr dk_str(const char *cz) {
    DkStr s;
    s.p = cz ? cz : "";
    s.n = cz ? strlen(cz) : 0;
    return s;
}

DkStr dk_strn(const char *p, size_t n) {
    DkStr s;
    s.p = p ? p : "";
    s.n = n;
    return s;
}

char *dk_cz(DkArena *a, DkStr s) {
    char *p = (char *)dk_alloc_noz(a, s.n + 1);
    if (s.n) memcpy(p, s.p, s.n);
    p[s.n] = 0;
    return p;
}

DkStr dk_str_dup(DkArena *a, DkStr s) { return dk_strn(dk_cz(a, s), s.n); }

bool dk_str_eq(DkStr a, DkStr b) { return a.n == b.n && (a.n == 0 || memcmp(a.p, b.p, a.n) == 0); }

bool dk_str_eqz(DkStr a, const char *cz) {
    size_t n = strlen(cz);
    return a.n == n && (n == 0 || memcmp(a.p, cz, n) == 0);
}

int dk_str_cmp(DkStr a, DkStr b) {
    size_t n = DK_MIN(a.n, b.n);
    int c = n ? memcmp(a.p, b.p, n) : 0;
    if (c) return c;
    return a.n < b.n ? -1 : a.n > b.n ? 1 : 0;
}

bool dk_str_startswith(DkStr s, DkStr prefix) {
    return prefix.n <= s.n && (prefix.n == 0 || memcmp(s.p, prefix.p, prefix.n) == 0);
}

bool dk_str_endswith(DkStr s, DkStr suffix) {
    return suffix.n <= s.n && (suffix.n == 0 || memcmp(s.p + s.n - suffix.n, suffix.p, suffix.n) == 0);
}

/* ---- UTF-8 -------------------------------------------------------------------------------------------------------- */

u32 dk_u8_next(const char **pp, const char *end) {
    const u8 *p = (const u8 *)*pp;
    const u8 *e = (const u8 *)end;
    DK_ASSERT(p < e);
    u32 c = p[0];
    if (c < 0x80) {
        *pp += 1;
        return c;
    }
    if (c >= 0xC2 && c <= 0xDF) {
        if (e - p >= 2 && (p[1] & 0xC0) == 0x80) {
            *pp += 2;
            return ((c & 0x1Fu) << 6) | (p[1] & 0x3Fu);
        }
    } else if (c >= 0xE0 && c <= 0xEF) {
        if (e - p >= 3) {
            u8 lo = 0x80, hi = 0xBF;
            if (c == 0xE0) lo = 0xA0;
            else if (c == 0xED) hi = 0x9F; /* no surrogates */
            if (p[1] >= lo && p[1] <= hi && (p[2] & 0xC0) == 0x80) {
                *pp += 3;
                return ((c & 0x0Fu) << 12) | ((p[1] & 0x3Fu) << 6) | (p[2] & 0x3Fu);
            }
        }
    } else if (c >= 0xF0 && c <= 0xF4) {
        if (e - p >= 4) {
            u8 lo = 0x80, hi = 0xBF;
            if (c == 0xF0) lo = 0x90;
            else if (c == 0xF4) hi = 0x8F; /* nothing above U+10FFFF */
            if (p[1] >= lo && p[1] <= hi && (p[2] & 0xC0) == 0x80 && (p[3] & 0xC0) == 0x80) {
                *pp += 4;
                return ((c & 0x07u) << 18) | ((p[1] & 0x3Fu) << 12) | ((p[2] & 0x3Fu) << 6) | (p[3] & 0x3Fu);
            }
        }
    }
    *pp += 1;
    return 0xFFFD;
}

u32 dk__u8_prev(const char *begin, const char **pp) {
    const char *p = *pp;
    DK_ASSERT(p > begin);
    if ((u8)p[-1] < 0x80) {
        *pp = p - 1;
        return (u8)p[-1];
    }
    for (const char *q = p - 1; q >= begin && p - q <= 4; q--) {
        if (((u8)*q & 0xC0) == 0x80) continue; /* a continuation byte: look further back for the lead */
        const char *r = q;
        u32 cp = dk_u8_next(&r, p);
        if (r == p) {
            *pp = q;
            return cp;
        }
        break;
    }
    *pp = p - 1;
    return 0xFFFD;
}

size_t dk_u8_put(char out[4], u32 cp) {
    if (cp >= 0xD800 && cp <= 0xDFFF) cp = 0xFFFD;
    if (cp > 0x10FFFF) cp = 0xFFFD;
    if (cp < 0x80) {
        out[0] = (char)cp;
        return 1;
    }
    if (cp < 0x800) {
        out[0] = (char)(0xC0 | (cp >> 6));
        out[1] = (char)(0x80 | (cp & 0x3F));
        return 2;
    }
    if (cp < 0x10000) {
        out[0] = (char)(0xE0 | (cp >> 12));
        out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[2] = (char)(0x80 | (cp & 0x3F));
        return 3;
    }
    out[0] = (char)(0xF0 | (cp >> 18));
    out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
    out[3] = (char)(0x80 | (cp & 0x3F));
    return 4;
}

size_t dk_u8_len(DkStr s) {
    const char *p = s.p, *end = s.p + s.n;
    size_t n = 0;
    while (p < end) {
        if ((u8)*p < 0x80) p++;
        else dk_u8_next(&p, end);
        n++;
    }
    return n;
}

bool dk_u8_valid(DkStr s) {
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        if ((u8)*p < 0x80) {
            p++;
            continue;
        }
        const char *q = p;
        u32 cp = dk_u8_next(&q, end);
        if (cp == 0xFFFD && q - p == 1) return false;
        p = q;
    }
    return true;
}

/* Byte offset of the code point index (0-based, at most the code point count) counted from the start of s. */
static const char *u8_advance(const char *p, const char *end, i64 count) {
    while (count > 0 && p < end) {
        if ((u8)*p < 0x80) p++;
        else dk_u8_next(&p, end);
        count--;
    }
    return p;
}

DkStr dk_u8_slice(DkStr s, i64 i, i64 j) {
    if (i < 0 || j < 0) {
        i64 len = (i64)dk_u8_len(s);
        if (i < 0) {
            i += len;
            if (i < 0) i = 0;
        }
        if (j < 0) {
            j += len;
            if (j < 0) j = 0;
        }
    }
    if (j <= i) return dk_strn(s.p, 0);
    const char *end = s.p + s.n;
    const char *start = u8_advance(s.p, end, i);
    const char *stop = u8_advance(start, end, j - i);
    return dk_strn(start, (size_t)(stop - start));
}

/* ---- search ------------------------------------------------------------------------------------------------------- */

/* Two-way string matching (Crochemore-Perrin), the algorithm CPython uses for long needles: linear time with no
 * table. rev reads both strings backwards, which turns the search for the first match into one for the last. */
static inline u8 at(const char *p, size_t n, size_t i, int rev) { return (u8)(rev ? p[n - 1 - i] : p[i]); }

/* The critical factorization position and the period of the needle's suffix after it. */
static void critical_factorization(const char *nd, size_t nn, int rev, size_t *crit, size_t *period) {
    i64 ms = -1, msr = -1;
    size_t j = 0, k = 1, p = 1, p1, p2;
    while (j + k < nn) {
        u8 a = at(nd, nn, j + k, rev), b = at(nd, nn, (size_t)(ms + (i64)k), rev);
        if (a < b) {
            j += k;
            k = 1;
            p = (size_t)((i64)j - ms);
        } else if (a == b) {
            if (k != p) k++;
            else {
                j += p;
                k = 1;
            }
        } else {
            ms = (i64)j++;
            k = p = 1;
        }
    }
    p1 = p;
    j = 0;
    k = p = 1;
    while (j + k < nn) {
        u8 a = at(nd, nn, j + k, rev), b = at(nd, nn, (size_t)(msr + (i64)k), rev);
        if (b < a) {
            j += k;
            k = 1;
            p = (size_t)((i64)j - msr);
        } else if (a == b) {
            if (k != p) k++;
            else {
                j += p;
                k = 1;
            }
        } else {
            msr = (i64)j++;
            k = p = 1;
        }
    }
    p2 = p;
    if (msr < ms) {
        *crit = (size_t)(ms + 1);
        *period = p1;
    } else {
        *crit = (size_t)(msr + 1);
        *period = p2;
    }
}

/* The offset (in the direction of reading) of the first occurrence of nd (nn >= 2) in h (hn >= nn), or SIZE_MAX. */
static size_t two_way(const char *h, size_t hn, const char *nd, size_t nn, int rev) {
    size_t suffix, period;
    critical_factorization(nd, nn, rev, &suffix, &period);
    bool periodic = suffix + period <= nn;
    if (periodic) {
        for (size_t i = 0; i < suffix; i++)
            if (at(nd, nn, i, rev) != at(nd, nn, i + period, rev)) {
                periodic = false;
                break;
            }
    }
    size_t j = 0;
    if (periodic) {
        size_t memory = 0;
        while (j <= hn - nn) {
            size_t i = DK_MAX(suffix, memory);
            while (i < nn && at(nd, nn, i, rev) == at(h, hn, i + j, rev)) i++;
            if (i >= nn) {
                /* The right half matched: check the left half beyond what is remembered. */
                i64 l = (i64)suffix - 1;
                while ((i64)memory < l + 1 && at(nd, nn, (size_t)l, rev) == at(h, hn, (size_t)l + j, rev)) l--;
                if (l + 1 <= (i64)memory) return j;
                j += period;
                memory = nn - period;
            } else {
                j += i - suffix + 1;
                memory = 0;
            }
        }
    } else {
        period = DK_MAX(suffix, nn - suffix) + 1;
        while (j <= hn - nn) {
            size_t i = suffix;
            while (i < nn && at(nd, nn, i, rev) == at(h, hn, i + j, rev)) i++;
            if (i >= nn) {
                i64 l = (i64)suffix - 1;
                while (l >= 0 && at(nd, nn, (size_t)l, rev) == at(h, hn, (size_t)l + j, rev)) l--;
                if (l < 0) return j;
                j += period;
            } else {
                j += i - suffix + 1;
            }
        }
    }
    return SIZE_MAX;
}

/* First occurrence of the non-empty needle in h; NULL when absent. */
static const char *search_fwd(const char *h, size_t hn, const char *nd, size_t nn) {
    if (hn < nn) return NULL;
    if (nn == 1) return (const char *)memchr(h, (u8)nd[0], hn);
    if (nn <= 16 || hn - nn < 64) {
        /* Short needles: the first byte through memchr, then a compare; bounded by nn * hn, which is linear. */
        const char *last = h + (hn - nn);
        for (const char *p = h; p <= last;) {
            p = (const char *)memchr(p, (u8)nd[0], (size_t)(last - p) + 1);
            if (!p) return NULL;
            if (memcmp(p, nd, nn) == 0) return p;
            p++;
        }
        return NULL;
    }
    size_t r = two_way(h, hn, nd, nn, 0);
    return r == SIZE_MAX ? NULL : h + r;
}

/* Last occurrence of the non-empty needle in h; NULL when absent. */
static const char *search_rev(const char *h, size_t hn, const char *nd, size_t nn) {
    if (hn < nn) return NULL;
    if (nn <= 16 || hn - nn < 64) {
        for (const char *p = h + (hn - nn);; p--) {
            if (p[0] == nd[0] && memcmp(p, nd, nn) == 0) return p;
            if (p == h) return NULL;
        }
    }
    size_t r = two_way(h, hn, nd, nn, 1);
    return r == SIZE_MAX ? NULL : h + (hn - nn - r);
}

/* Python's ADJUST_INDICES: slice semantics for [start, end) over len bytes. start may stay above len. */
static void adjust(i64 *start, i64 *end, i64 len) {
    if (*end > len) *end = len;
    else if (*end < 0) {
        *end += len;
        if (*end < 0) *end = 0;
    }
    if (*start < 0) {
        *start += len;
        if (*start < 0) *start = 0;
    }
}

i64 dk_str_find(DkStr hay, DkStr needle, i64 start, i64 end) {
    adjust(&start, &end, (i64)hay.n);
    if (end - start < (i64)needle.n) return -1;
    if (needle.n == 0) return start;
    const char *r = search_fwd(hay.p + start, (size_t)(end - start), needle.p, needle.n);
    return r ? (i64)(r - hay.p) : -1;
}

i64 dk_str_rfind(DkStr hay, DkStr needle, i64 start, i64 end) {
    adjust(&start, &end, (i64)hay.n);
    if (end - start < (i64)needle.n) return -1;
    if (needle.n == 0) return end;
    const char *r = search_rev(hay.p + start, (size_t)(end - start), needle.p, needle.n);
    return r ? (i64)(r - hay.p) : -1;
}

bool dk_str_contains(DkStr hay, DkStr needle) {
    if (needle.n == 0) return true;
    return search_fwd(hay.p, hay.n, needle.p, needle.n) != NULL;
}

size_t dk_str_count(DkStr hay, DkStr needle) {
    if (needle.n == 0) return dk_u8_len(hay) + 1; /* between every code point and at both ends */
    size_t count = 0;
    const char *p = hay.p, *end = hay.p + hay.n;
    for (;;) {
        const char *r = search_fwd(p, (size_t)(end - p), needle.p, needle.n);
        if (!r) return count;
        count++;
        p = r + needle.n;
    }
}

i64 dk_str_findc(DkStr s, char c) {
    if (s.n == 0) return -1;
    const char *r = (const char *)memchr(s.p, (u8)c, s.n);
    return r ? (i64)(r - s.p) : -1;
}

DkStr dk_str_slice(DkStr s, i64 i, i64 j) {
    i64 len = (i64)s.n;
    if (i < 0) {
        i += len;
        if (i < 0) i = 0;
    } else if (i > len) {
        i = len;
    }
    if (j < 0) {
        j += len;
        if (j < 0) j = 0;
    } else if (j > len) {
        j = len;
    }
    if (j < i) j = i;
    return dk_strn(s.p + i, (size_t)(j - i));
}

/* ---- strip -------------------------------------------------------------------------------------------------------- */

DkStr dk_str_lstrip(DkStr s) {
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        const char *q = p;
        u32 cp = (u8)*p < 0x80 ? (u32)(u8)*q++ : dk_u8_next(&q, end);
        if (!dk_cp_isspace(cp)) break;
        p = q;
    }
    return dk_strn(p, (size_t)(end - p));
}

DkStr dk_str_rstrip(DkStr s) {
    const char *end = s.p + s.n;
    while (end > s.p) {
        const char *q = end;
        u32 cp = dk__u8_prev(s.p, &q);
        if (!dk_cp_isspace(cp)) break;
        end = q;
    }
    return dk_strn(s.p, (size_t)(end - s.p));
}

DkStr dk_str_strip(DkStr s) { return dk_str_rstrip(dk_str_lstrip(s)); }

static bool in_charset(DkStr chars, u32 cp) {
    const char *p = chars.p, *end = chars.p + chars.n;
    while (p < end)
        if (dk_u8_next(&p, end) == cp) return true;
    return false;
}

DkStr dk_str_lstrip_chars(DkStr s, DkStr chars) {
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        const char *q = p;
        u32 cp = dk_u8_next(&q, end);
        if (!in_charset(chars, cp)) break;
        p = q;
    }
    return dk_strn(p, (size_t)(end - p));
}

DkStr dk_str_rstrip_chars(DkStr s, DkStr chars) {
    const char *end = s.p + s.n;
    while (end > s.p) {
        const char *q = end;
        u32 cp = dk__u8_prev(s.p, &q);
        if (!in_charset(chars, cp)) break;
        end = q;
    }
    return dk_strn(s.p, (size_t)(end - s.p));
}

DkStr dk_str_strip_chars(DkStr s, DkStr chars) {
    return dk_str_rstrip_chars(dk_str_lstrip_chars(s, chars), chars);
}

DkStr dk_str_removeprefix(DkStr s, DkStr prefix) {
    if (prefix.n && dk_str_startswith(s, prefix)) return dk_strn(s.p + prefix.n, s.n - prefix.n);
    return s;
}

DkStr dk_str_removesuffix(DkStr s, DkStr suffix) {
    if (suffix.n && dk_str_endswith(s, suffix)) return dk_strn(s.p, s.n - suffix.n);
    return s;
}

/* ---- split -------------------------------------------------------------------------------------------------------- */

static void push_view(DkStrVec *v, const char *p, size_t n) {
    DkStr s;
    s.p = p;
    s.n = n;
    dk_vec_push(v, s);
}

/* The code point at p (p < end) and its byte length. */
static inline u32 cp_at(const char *p, const char *end, size_t *len) {
    if ((u8)*p < 0x80) {
        *len = 1;
        return (u8)*p;
    }
    const char *q = p;
    u32 cp = dk_u8_next(&q, end);
    *len = (size_t)(q - p);
    return cp;
}

static DkStrVec split_whitespace(DkStr s, int maxsplit) {
    DkStrVec v = {0};
    const char *p = s.p, *end = s.p + s.n;
    size_t l;
    while (maxsplit != 0) {
        while (p < end && dk_cp_isspace(cp_at(p, end, &l))) p += l;
        if (p == end) break;
        const char *start = p;
        while (p < end && !dk_cp_isspace(cp_at(p, end, &l))) p += l;
        push_view(&v, start, (size_t)(p - start));
        if (maxsplit > 0) maxsplit--;
    }
    if (p < end) {
        /* Only when the limit was reached: skip whitespace, the rest (trailing whitespace included) is the last field. */
        while (p < end && dk_cp_isspace(cp_at(p, end, &l))) p += l;
        if (p < end) push_view(&v, p, (size_t)(end - p));
    }
    return v;
}

DkStrVec dk_str_split(DkStr s, DkStr sep, int maxsplit) {
    if (sep.n == 0) return split_whitespace(s, maxsplit);
    DkStrVec v = {0};
    const char *p = s.p, *end = s.p + s.n;
    while (maxsplit != 0) {
        const char *r = search_fwd(p, (size_t)(end - p), sep.p, sep.n);
        if (!r) break;
        push_view(&v, p, (size_t)(r - p));
        p = r + sep.n;
        if (maxsplit > 0) maxsplit--;
    }
    push_view(&v, p, (size_t)(end - p));
    return v;
}

static void reverse_vec(DkStrVec *v) {
    for (size_t i = 0, j = v->n; i + 1 < j; i++, j--) {
        DkStr t = v->v[i];
        v->v[i] = v->v[j - 1];
        v->v[j - 1] = t;
    }
}

DkStrVec dk_str_rsplit(DkStr s, DkStr sep, int maxsplit) {
    DkStrVec v = {0};
    const char *begin = s.p, *end = s.p + s.n;
    if (sep.n == 0) {
        while (maxsplit != 0) {
            while (end > begin) {
                const char *q = end;
                if (!dk_cp_isspace(dk__u8_prev(begin, &q))) break;
                end = q;
            }
            if (end == begin) break;
            const char *stop = end;
            while (end > begin) {
                const char *q = end;
                if (dk_cp_isspace(dk__u8_prev(begin, &q))) break;
                end = q;
            }
            push_view(&v, end, (size_t)(stop - end));
            if (maxsplit > 0) maxsplit--;
        }
        if (end > begin) {
            /* Only when the limit was reached: the rest, leading whitespace included, minus trailing whitespace. */
            while (end > begin) {
                const char *q = end;
                if (!dk_cp_isspace(dk__u8_prev(begin, &q))) break;
                end = q;
            }
            if (end > begin) push_view(&v, begin, (size_t)(end - begin));
        }
        reverse_vec(&v);
        return v;
    }
    while (maxsplit != 0) {
        const char *r = search_rev(begin, (size_t)(end - begin), sep.p, sep.n);
        if (!r) break;
        push_view(&v, r + sep.n, (size_t)(end - (r + sep.n)));
        end = r;
        if (maxsplit > 0) maxsplit--;
    }
    push_view(&v, begin, (size_t)(end - begin));
    reverse_vec(&v);
    return v;
}

/* Length of the line boundary starting at p (0 when none): \n \r \r\n \v \f \x1c \x1d \x1e U+0085 U+2028 U+2029. */
static size_t line_break_len(const char *p, const char *end) {
    u8 c = (u8)*p;
    if (c == '\r') return (p + 1 < end && p[1] == '\n') ? 2 : 1;
    if (c == '\n' || c == 0x0B || c == 0x0C || (c >= 0x1C && c <= 0x1E)) return 1;
    if (c == 0xC2 && p + 1 < end && (u8)p[1] == 0x85) return 2;
    if (c == 0xE2 && p + 2 < end && (u8)p[1] == 0x80 && ((u8)p[2] == 0xA8 || (u8)p[2] == 0xA9)) return 3;
    return 0;
}

DkStrVec dk_str_splitlines(DkStr s, bool keepends) {
    DkStrVec v = {0};
    const char *p = s.p, *end = s.p + s.n, *start = p;
    while (p < end) {
        size_t bl = (u8)*p < 0x20 || (u8)*p >= 0x80 ? line_break_len(p, end) : 0;
        if (bl) {
            push_view(&v, start, (size_t)(p - start) + (keepends ? bl : 0));
            p += bl;
            start = p;
        } else {
            p++;
        }
    }
    if (start < end) push_view(&v, start, (size_t)(end - start));
    return v;
}

bool dk_str_partition(DkStr s, DkStr sep, DkStr *before, DkStr *after) {
    DK_ASSERT(sep.n > 0); /* Python raises ValueError("empty separator") */
    const char *r = search_fwd(s.p, s.n, sep.p, sep.n);
    if (!r) {
        *before = s;
        *after = dk_strn(s.p + s.n, 0);
        return false;
    }
    *before = dk_strn(s.p, (size_t)(r - s.p));
    *after = dk_strn(r + sep.n, (size_t)(s.p + s.n - (r + sep.n)));
    return true;
}

bool dk_str_rpartition(DkStr s, DkStr sep, DkStr *before, DkStr *after) {
    DK_ASSERT(sep.n > 0);
    const char *r = search_rev(s.p, s.n, sep.p, sep.n);
    if (!r) {
        *before = dk_strn(s.p, 0); /* Python: ('', '', s) */
        *after = s;
        return false;
    }
    *before = dk_strn(s.p, (size_t)(r - s.p));
    *after = dk_strn(r + sep.n, (size_t)(s.p + s.n - (r + sep.n)));
    return true;
}

/* ---- replace, join, concat, repeat -------------------------------------------------------------------------------- */

static DkStr finish(char *p, size_t n) {
    p[n] = 0;
    return dk_strn(p, n);
}

DkStr dk_str_replace(DkArena *a, DkStr s, DkStr old, DkStr new_, int count) {
    if (count == 0) return s;
    if (old.n == 0) {
        /* Python inserts `new` before every code point and at the end: len + 1 places, the first `count` of them. */
        size_t places = dk_u8_len(s) + 1;
        size_t k = (count < 0 || (size_t)count > places) ? places : (size_t)count;
        if (new_.n && k > (SIZE_MAX - s.n - 1) / new_.n) dk_fatal("out of memory (replace)");
        char *out = (char *)dk_alloc_noz(a, s.n + k * new_.n + 1);
        char *o = out;
        const char *p = s.p, *end = s.p + s.n;
        for (size_t i = 0; i < k; i++) {
            memcpy(o, new_.p, new_.n);
            o += new_.n;
            if (p < end) {
                const char *q = p;
                if ((u8)*q < 0x80) q++;
                else dk_u8_next(&q, end);
                memcpy(o, p, (size_t)(q - p));
                o += q - p;
                p = q;
            }
        }
        memcpy(o, p, (size_t)(end - p));
        o += end - p;
        return finish(out, (size_t)(o - out));
    }
    /* Find the matches first, so that the result is allocated once. */
    size_t found = 0;
    const char *p = s.p, *end = s.p + s.n;
    while (count < 0 || found < (size_t)count) {
        const char *r = search_fwd(p, (size_t)(end - p), old.p, old.n);
        if (!r) break;
        found++;
        p = r + old.n;
    }
    if (found == 0) return s;
    size_t out_n;
    if (new_.n >= old.n) {
        if ((new_.n - old.n) && found > (SIZE_MAX - s.n - 1) / (new_.n - old.n)) dk_fatal("out of memory (replace)");
        out_n = s.n + found * (new_.n - old.n);
    } else {
        out_n = s.n - found * (old.n - new_.n);
    }
    char *out = (char *)dk_alloc_noz(a, out_n + 1);
    char *o = out;
    p = s.p;
    for (size_t i = 0; i < found; i++) {
        const char *r = search_fwd(p, (size_t)(end - p), old.p, old.n);
        memcpy(o, p, (size_t)(r - p));
        o += r - p;
        memcpy(o, new_.p, new_.n);
        o += new_.n;
        p = r + old.n;
    }
    memcpy(o, p, (size_t)(end - p));
    o += end - p;
    return finish(out, (size_t)(o - out));
}

DkStr dk_str_join(DkArena *a, DkStr sep, const DkStr *items, size_t count) {
    if (count == 0) return finish((char *)dk_alloc_noz(a, 1), 0);
    size_t total = sep.n * (count - 1);
    for (size_t i = 0; i < count; i++) {
        if (items[i].n > SIZE_MAX / 2 - total) dk_fatal("out of memory (join)");
        total += items[i].n;
    }
    char *out = (char *)dk_alloc_noz(a, total + 1);
    char *o = out;
    for (size_t i = 0; i < count; i++) {
        if (i && sep.n) {
            memcpy(o, sep.p, sep.n);
            o += sep.n;
        }
        if (items[i].n) memcpy(o, items[i].p, items[i].n);
        o += items[i].n;
    }
    return finish(out, total);
}

DkStr dk_str_concat(DkArena *a, DkStr x, DkStr y) {
    char *out = (char *)dk_alloc_noz(a, x.n + y.n + 1);
    if (x.n) memcpy(out, x.p, x.n);
    if (y.n) memcpy(out + x.n, y.p, y.n);
    return finish(out, x.n + y.n);
}

DkStr dk_str_repeat(DkArena *a, DkStr s, size_t times) {
    if (s.n && times > (SIZE_MAX / 2) / s.n) dk_fatal("out of memory (repeat)");
    size_t total = s.n * times;
    char *out = (char *)dk_alloc_noz(a, total + 1);
    if (s.n == 1) memset(out, (u8)s.p[0], times);
    else
        for (size_t i = 0; i < times; i++) memcpy(out + i * s.n, s.p, s.n);
    return finish(out, total);
}

/* ---- tabs and padding --------------------------------------------------------------------------------------------- */

DkStr dk_str_expandtabs(DkArena *a, DkStr s, int tabsize) {
    DkBuf b;
    dk_buf_init(&b, a);
    dk_buf_reserve(&b, s.n);
    const char *p = s.p, *end = s.p + s.n;
    i64 col = 0;
    while (p < end) {
        char c = *p;
        if (c == '\t') {
            /* tabsize <= 0 removes the tab; the column is not advanced then, as in Python. */
            if (tabsize > 0) {
                i64 add = tabsize - col % tabsize;
                col += add;
                for (i64 i = 0; i < add; i++) dk_buf_putc(&b, ' ');
            }
            p++;
            continue;
        }
        const char *q = p;
        if ((u8)c < 0x80) q++;
        else dk_u8_next(&q, end);
        dk_buf_putn(&b, p, (size_t)(q - p));
        col++;
        if (c == '\n' || c == '\r') col = 0;
        p = q;
    }
    dk_buf_putn(&b, "", 0);
    return dk_buf_str(&b);
}

static DkStr pad(DkArena *a, DkStr s, size_t width, u32 fill, size_t left, size_t right) {
    (void)width;
    char fb[4];
    size_t fn = dk_u8_put(fb, fill);
    char *out = (char *)dk_alloc_noz(a, s.n + (left + right) * fn + 1);
    char *o = out;
    for (size_t i = 0; i < left; i++, o += fn) memcpy(o, fb, fn);
    if (s.n) memcpy(o, s.p, s.n);
    o += s.n;
    for (size_t i = 0; i < right; i++, o += fn) memcpy(o, fb, fn);
    return finish(out, (size_t)(o - out));
}

DkStr dk_str_ljust(DkArena *a, DkStr s, size_t width, u32 fill) {
    size_t len = dk_u8_len(s);
    if (len >= width) return s;
    return pad(a, s, width, fill, 0, width - len);
}

DkStr dk_str_rjust(DkArena *a, DkStr s, size_t width, u32 fill) {
    size_t len = dk_u8_len(s);
    if (len >= width) return s;
    return pad(a, s, width, fill, width - len, 0);
}

DkStr dk_str_center(DkArena *a, DkStr s, size_t width, u32 fill) {
    size_t len = dk_u8_len(s);
    if (len >= width) return s;
    size_t marg = width - len;
    size_t left = marg / 2 + (marg & width & 1); /* CPython's rule for the odd column */
    return pad(a, s, width, fill, left, marg - left);
}

DkStr dk_str_zfill(DkArena *a, DkStr s, size_t width) {
    size_t len = dk_u8_len(s);
    if (len >= width) return s;
    size_t fill = width - len;
    char *out = (char *)dk_alloc_noz(a, s.n + fill + 1);
    size_t sign = (s.n && (s.p[0] == '+' || s.p[0] == '-')) ? 1 : 0;
    if (sign) out[0] = s.p[0];
    memset(out + sign, '0', fill);
    memcpy(out + sign + fill, s.p + sign, s.n - sign);
    return finish(out, s.n + fill);
}

/* ---- UTF-16 ------------------------------------------------------------------------------------------------------- */

wchar_t *dk_to_w(DkArena *a, DkStr s) {
    wchar_t *out = (wchar_t *)dk_alloc_noz(a, (s.n + 1) * sizeof(wchar_t));
    wchar_t *o = out;
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        u32 cp = (u8)*p < 0x80 ? (u32)(u8)*p++ : dk_u8_next(&p, end);
        if (cp >= 0x10000) {
            cp -= 0x10000;
            *o++ = (wchar_t)(0xD800 + (cp >> 10));
            *o++ = (wchar_t)(0xDC00 + (cp & 0x3FF));
        } else {
            *o++ = (wchar_t)cp;
        }
    }
    *o = 0;
    return out;
}

wchar_t *dk_to_wz(DkArena *a, const char *cz) { return dk_to_w(a, dk_str(cz)); }

DkStr dk_from_w(DkArena *a, const wchar_t *w, i64 n) {
    size_t len = n < 0 ? wcslen(w) : (size_t)n;
    char *out = (char *)dk_alloc_noz(a, len * 3 + 1);
    char *o = out;
    for (size_t i = 0; i < len; i++) {
        u32 c = w[i];
        if (c >= 0xD800 && c <= 0xDBFF && i + 1 < len && w[i + 1] >= 0xDC00 && w[i + 1] <= 0xDFFF) {
            c = 0x10000 + ((c - 0xD800) << 10) + (w[i + 1] - 0xDC00);
            i++;
        } else if (c >= 0xD800 && c <= 0xDFFF) {
            c = 0xFFFD; /* an unpaired surrogate */
        }
        o += dk_u8_put(o, c);
    }
    size_t used = (size_t)(o - out);
    out = (char *)dk_arena_realloc(a, out, len * 3 + 1, used + 1);
    return finish(out, used);
}

/* ---- builder ------------------------------------------------------------------------------------------------------ */

void dk_buf_init(DkBuf *b, DkArena *a) {
    b->p = NULL;
    b->n = 0;
    b->cap = 0;
    b->a = a;
}

void dk_buf_reserve(DkBuf *b, size_t extra) {
    if (extra > SIZE_MAX / 4 - b->n) dk_fatal("out of memory (string builder)");
    size_t need = b->n + extra + 1;
    if (need <= b->cap) return;
    size_t ncap = b->cap * 2;
    if (ncap < need) ncap = need;
    if (ncap < 64) ncap = 64;
    if (b->a) b->p = (char *)dk_arena_realloc(b->a, b->p, b->cap, ncap);
    else b->p = (char *)dk_xrealloc(b->p, ncap);
    b->cap = ncap;
}

void dk_buf_putn(DkBuf *b, const void *p, size_t n) {
    dk_buf_reserve(b, n);
    if (n) memcpy(b->p + b->n, p, n);
    b->n += n;
    b->p[b->n] = 0;
}

void dk_buf_put(DkBuf *b, DkStr s) { dk_buf_putn(b, s.p, s.n); }
void dk_buf_putz(DkBuf *b, const char *cz) { dk_buf_putn(b, cz, strlen(cz)); }

void dk_buf_putc(DkBuf *b, char c) {
    dk_buf_reserve(b, 1);
    b->p[b->n++] = c;
    b->p[b->n] = 0;
}

void dk_buf_putcp(DkBuf *b, u32 cp) {
    char t[4];
    size_t n = dk_u8_put(t, cp);
    dk_buf_putn(b, t, n);
}

void dk_buf_vprintf(DkBuf *b, const char *fmt, va_list ap) {
    va_list ap2;
    va_copy(ap2, ap);
    int need = vsnprintf(b->p ? b->p + b->n : NULL, b->p ? b->cap - b->n : 0, fmt, ap2);
    va_end(ap2);
    if (need < 0) dk_panic(__FILE__, __LINE__, "vsnprintf failed for \"%s\"", fmt);
    if (b->p && (size_t)need < b->cap - b->n) {
        b->n += (size_t)need;
        return;
    }
    dk_buf_reserve(b, (size_t)need);
    vsnprintf(b->p + b->n, (size_t)need + 1, fmt, ap);
    b->n += (size_t)need;
}

void dk_buf_printf(DkBuf *b, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    dk_buf_vprintf(b, fmt, ap);
    va_end(ap);
}

void dk_buf_clear(DkBuf *b) {
    b->n = 0;
    if (b->p) b->p[0] = 0;
}

DkStr dk_buf_str(const DkBuf *b) { return dk_strn(b->p, b->n); }

char *dk_buf_cz(DkBuf *b) {
    if (!b->p) return (char *)"";
    b->p[b->n] = 0;
    return b->p;
}

void dk_buf_free(DkBuf *b) {
    if (!b->a) dk_xfree(b->p);
    b->p = NULL;
    b->n = b->cap = 0;
}
